import React, { useEffect, useMemo, useRef, useState } from 'react';
import './ProductModules.css';
import './RequirementLifecycle.css';
import { api } from './api';
import {
  Activity, AlertTriangle, ArrowUpRight, BatteryCharging, Bot, Box,
  Check, ChevronDown, ChevronRight, CircleDollarSign, Cpu, Download,
  Eye, Factory, Gauge, GitCompare, GripVertical, Hexagon, Layers3,
  Lock, Maximize2, Minus, Move, Package, Play, Plus, RotateCcw,
  Ruler, Save, Search, ShieldCheck, SlidersHorizontal, Sparkles,
  Thermometer, Truck, Upload, Wind, Workflow, Wrench, Zap,
  Target, Flag, RefreshCw, Timer, Bell, UserCheck
} from 'lucide-react';

const Button = ({children, primary=false, onClick, className=''}) => <button onClick={onClick} className={`${primary?'primary':'outline'} ${className}`}>{children}</button>;

export function MissionControl({notify,projectId}){
  const [goals,setGoals]=useState([]),[loops,setLoops]=useState([]),[runs,setRuns]=useState([]),[state,setState]=useState(null),[completion,setCompletion]=useState(null),[requirements,setRequirements]=useState([]),[baselines,setBaselines]=useState([]),[verificationTasks,setVerificationTasks]=useState([]),[requirementText,setRequirementText]=useState('4인승 도심형 전기차. 전장 4미터 이하, 주행거리 450킬로미터 이상, 제조원가 3천만 원 이하.'),[selectedRequirementId,setSelectedRequirementId]=useState(null),[revisionTarget,setRevisionTarget]=useState(''),[evidenceId,setEvidenceId]=useState(''),[tab,setTab]=useState('목표 계층');
  const load=()=>Promise.all([api.goals(projectId),api.loops(projectId),api.runs(projectId),api.projectState(projectId),api.completion(projectId),api.requirements(projectId),api.requirementBaselines(projectId),api.verificationTasks(projectId)]).then(([g,l,u,s,c,r,b,v])=>{setGoals(g);setLoops(l);setRuns(u);setState(s);setCompletion(c);setRequirements(r);setBaselines(b);setVerificationTasks(v)}).catch(()=>notify('미션 컨트롤 API 연결을 확인하세요'));
  useEffect(()=>{if(projectId){setSelectedRequirementId(null);load()}},[projectId]);
  const children=id=>goals.filter(g=>g.parentId===id);
  const step=id=>api.stepLoop(id).then(x=>{setLoops(ls=>ls.map(l=>l.id===id?x:l));notify(`${x.name} · 반복 ${x.iteration} 실행`)}).catch(()=>notify('루프 중단 조건에 도달했습니다'));
  const draft=()=>api.createRequirementDrafts(requirementText,projectId).then(x=>{notify(`${x.drafts.length}개 요구사항 초안을 생성했습니다`);load()}).catch(e=>notify(`초안 생성 실패 · ${e.message}`));
  const approve=id=>api.approveRequirement(id).then(()=>{notify(`${id} 검토 승인을 기록했습니다`);load()}).catch(e=>notify(`승인 불가 · ${e.message}`));
  const baseline=()=>{const ids=requirements.filter(x=>x.lifecycleStatus==='approved').map(x=>x.id);return api.createRequirementBaseline(ids,projectId).then(x=>{notify(`요구사항 기준선 v${x.baseline.version}을 고정했습니다`);load()}).catch(e=>notify(`기준선 생성 불가 · ${e.message}`))};
  const selectedRequirement=requirements.find(x=>x.id===selectedRequirementId)||requirements.find(x=>x.lifecycleStatus==='baselined')||requirements[0];
  const selectRequirement=r=>{setSelectedRequirementId(r.id);setRevisionTarget(String(r.target??''));setEvidenceId(r.verificationEvidenceId||'')};
  const revise=()=>{const target=Number(revisionTarget);if(!selectedRequirement||!Number.isFinite(target))return notify('유효한 개정 목표값을 입력하세요');api.reviseRequirement(selectedRequirement.id,{target}).then(x=>{notify(`${x.requirement.id} 개정 초안을 생성했습니다`);setSelectedRequirementId(x.requirement.id);load()}).catch(e=>notify(`개정 실패 · ${e.message}`))};
  const verify=status=>{if(!selectedRequirement||!evidenceId.trim())return notify('시뮬레이션 또는 시험 증거 ID가 필요합니다');api.verifyRequirement(selectedRequirement.id,status,evidenceId.trim()).then(()=>{notify(`${selectedRequirement.id} 검증을 ${status==='pass'?'통과':'실패'}로 기록했습니다`);load()}).catch(e=>notify(`검증 기록 실패 · ${e.message}`))};
  const resumeRun=run=>api.resumeRun(run.id,run.parameters,run.gate==='requirement_baseline'?'baseline_approved':'expert_adjustment').then(x=>{notify(`${run.id.slice(0,8)} → ${x.id.slice(0,8)} 실행을 재개했습니다`);load()}).catch(e=>notify(`재개 불가 · ${e.message}`));
  const labels={goal_definition:'목표 정의',designing:'설계 중',virtual_validation:'가상 검증',manufacturing_review:'제조 검토',prototyping:'시제품 제작',physical_test:'물리 시험',approval_pending:'승인 대기',released:'릴리스',field_learning:'운행 학습'};
  return <div className="mission-control">
    <section className="mission-hero"><div><span>NORTH STAR METRIC</span><h1>검증 완료 설계당<br/><b>소요 시간과 비용</b></h1><p>모든 목표·루프·증거·승인 상태를 하나의 실행 체계로 관리합니다.</p></div><div className="north-metrics"><div><small>검증 설계 리드타임</small><b>11.4<em>일</em></b><span>−18% vs baseline</span></div><div><small>요구사항 충족률</small><b>93<em>%</em></b><span>목표 98%</span></div><div><small>설계 자동화율</small><b>76<em>%</em></b><span>목표 80%</span></div></div></section>
    <div className="mission-tabs">{['목표 계층','요구사항 기준선','자율 루프','실행·이관','상태·완성 판정'].map(x=><button className={tab===x?'active':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}<Button onClick={load}><RefreshCw size={13}/>새로고침</Button></div>
    {tab==='목표 계층'&&<div className="goal-layout"><section className="goal-tree panel"><div className="panel-title"><div><Target size={15}/><h3>L0–L4 목표 그래프</h3></div><Button><Plus size={13}/>목표 추가</Button></div>{goals.filter(g=>!g.parentId).map(g=><GoalBranch key={g.id} goal={g} children={children}/>)}</section><aside className="goal-detail panel"><div className="panel-title"><div><h3>목표 건강도</h3></div></div><div className="goal-health"><strong>72</strong><span>GOAL HEALTH<br/><em>2개 목표 주의 필요</em></span></div>{goals.filter(g=>g.level==='L2').map(g=><div className="health-row" key={g.id}><span className={g.status}/><div><b>{g.name}</b><small>신뢰도 {Math.round((g.confidence||0)*100)}% · {g.ownerAgent}</small></div><em>{g.actual}{g.unit}</em></div>)}</aside></div>}
    {tab==='요구사항 기준선'&&<div className="requirement-workspace"><section className="panel requirement-compose"><div className="panel-title"><div><Target size={15}/><h3>자연어 → 검토 초안</h3></div><span className="count">사람 승인 필수</span></div><textarea value={requirementText} onChange={e=>setRequirementText(e.target.value)} aria-label="차량 요구사항 입력"/><Button primary onClick={draft}><Sparkles size={13}/>구조화 초안 생성</Button><div className="baseline-summary"><span><small>활성 기준선</small><b>{baselines.find(x=>x.status==='active')?`v${baselines.find(x=>x.status==='active').version}`:'없음'}</b></span><span><small>승인 대기</small><b>{requirements.filter(x=>x.lifecycleStatus==='draft').length}</b></span><span><small>재검증 작업</small><b>{verificationTasks.filter(x=>x.status!=='complete').length}</b></span></div></section><section className="panel requirement-list"><div className="panel-title"><div><GitCompare size={15}/><h3>요구사항 계보와 검증</h3></div><Button onClick={baseline} primary><Lock size={13}/>승인본 기준선 고정</Button></div>{requirements.slice().reverse().map(r=><div onClick={()=>selectRequirement(r)} className={`requirement-row ${r.lifecycleStatus||'legacy'} ${selectedRequirement?.id===r.id?'selected':''}`} key={r.id}><span className="req-id">{r.id}<small>rev {r.revision||1}</small></span><div><b>{r.title}</b><small>{r.operator} {r.target} {r.unit} · {r.category} · 검증 {r.status}</small></div><em>{r.lifecycleStatus||'active'}</em>{r.lifecycleStatus==='draft'&&<button onClick={e=>{e.stopPropagation();approve(r.id)}}>검토 승인</button>}</div>)}</section><aside className="panel requirement-inspector"><div className="panel-title"><div><ShieldCheck size={15}/><h3>개정·검증 콘솔</h3></div></div>{selectedRequirement?<><div className="selected-requirement"><span>{selectedRequirement.id} · REV {selectedRequirement.revision||1}</span><b>{selectedRequirement.title}</b><small>{selectedRequirement.lifecycleStatus||'active'} · {selectedRequirement.status}</small></div><label><span>개정 목표값</span><div><input value={revisionTarget} onChange={e=>setRevisionTarget(e.target.value)} inputMode="decimal"/><em>{selectedRequirement.unit}</em></div></label><Button onClick={revise}><GitCompare size={13}/>새 개정 초안</Button><label><span>시험·시뮬레이션 증거 ID</span><input value={evidenceId} onChange={e=>setEvidenceId(e.target.value)} placeholder="예: SIM-RANGE-2026-014"/></label><div className="verification-actions"><button onClick={()=>verify('fail')}><AlertTriangle size={12}/>실패 기록</button><button onClick={()=>verify('pass')}><Check size={12}/>통과 기록</button></div><div className="task-impact"><b>연결된 재검증</b>{verificationTasks.filter(x=>x.requirementId===selectedRequirement.id).length?verificationTasks.filter(x=>x.requirementId===selectedRequirement.id).map(x=><span key={x.id}><i className={x.status}/><small>{x.method}</small><em>{x.status}</em></span>):<small>기준선 변경으로 생성된 작업 없음</small>}</div></>:<div className="empty-state small"><Target size={24}/><span>요구사항을 선택하세요.</span></div>}</aside></div>}
    {tab==='자율 루프'&&<div className="loops-board"><div className="speed-lanes"><div><span>INNER · 초–분</span><p>형상 수정 · 규칙 검사 · 빠른 평가</p></div><ChevronRight size={18}/><div><span>MIDDLE · 시간–일</span><p>고정밀 해석 · 제조 검토</p></div><ChevronRight size={18}/><div><span>OUTER · 주–월</span><p>시제품 · 물리 시험 · 운행 학습</p></div></div><div className="loop-grid">{loops.map(l=><div className={`loop-card ${l.status}`} key={l.id}><div><span className="loop-icon"><RefreshCw size={15}/></span><em>{l.speed}</em><i className={l.status}/></div><b>{l.name}</b><p>종료: {l.exitCondition}</p><div className="loop-progress"><i style={{width:`${l.progress}%`}}/></div><footer><span>반복 {l.iteration}{l.maxIterations?` / ${l.maxIterations}`:''}</span><button disabled={l.status==='blocked'||l.status==='complete'} onClick={()=>step(l.id)}><Play size={12}/>1회 실행</button></footer>{l.blocker&&<small><AlertTriangle size={11}/>{l.blocker}</small>}</div>)}</div></div>}
    {tab==='실행·이관'&&<div className="run-console"><section className="panel run-history"><div className="panel-title"><div><Workflow size={15}/><h3>자율 실행 계보</h3><span className="count">{runs.length}</span></div></div>{runs.length?runs.map(run=><div className={`run-row ${run.status}`} key={run.id}><span className="run-status"><i/>{run.status}</span><div><b>{run.prompt||'자율 설계 실행'}</b><small>{run.id.slice(0,8)} · 반복 {run.iteration||1}/{run.maxIterations||3} · {run.stage}</small>{run.parentRunId&&<em>↳ 부모 실행 {run.parentRunId.slice(0,8)} · {run.resumeReason}</em>}</div><strong>{run.progress}%</strong>{['blocked','failed','needs_review'].includes(run.status)&&!run.resumedByRunId?<button onClick={()=>resumeRun(run)}><RefreshCw size={12}/>검토 후 재개</button>:run.resumedByRunId?<span className="resumed">재개됨 → {run.resumedByRunId.slice(0,8)}</span>:null}</div>):<div className="empty-state"><Workflow size={30}/><b>실행 이력 없음</b><span>프로젝트 스튜디오에서 자율 설계를 시작하세요.</span></div>}</section><aside className="panel handoff-policy"><div className="panel-title"><div><UserCheck size={15}/><h3>인간 이관 정책</h3></div></div><div className="handoff-flow"><span><Target size={14}/>기준선 승인 대기</span><ChevronDown size={13}/><span><AlertTriangle size={14}/>최적화 정체</span><ChevronDown size={13}/><span><UserCheck size={14}/>전문가 파라미터 검토</span><ChevronDown size={13}/><span><RefreshCw size={14}/>계보 유지 재실행</span></div><p>완료·진행 중인 실행은 재개할 수 없으며, 하나의 종료 실행에서 새 실행은 한 번만 파생됩니다.</p></aside></div>}
    {tab==='상태·완성 판정'&&<div className="state-layout"><section className="state-machine panel"><div className="panel-title"><div><Workflow size={15}/><h3>프로젝트 상태 머신</h3></div><span className="current-state">현재 · {labels[state?.state]||'로딩'}</span></div><div className="state-flow">{Object.keys(labels).map((x,i)=><React.Fragment key={x}><div className={`${state?.state===x?'active':''} ${state?.history?.some(h=>h.to===x)?'done':''}`}><span>{i+1}</span><b>{labels[x]}</b></div>{i<8&&<ChevronRight size={16}/>}</React.Fragment>)}</div><div className="state-evidence"><ShieldCheck size={16}/><div><b>현재 전환 조건</b><p>모든 필수 가상 시험 통과 · 증거 신뢰도 95% 이상 · 중대 안전 위반 0건</p></div></div></section><aside className="completion panel"><div className="panel-title"><div><Flag size={15}/><h3>완성 판정</h3></div></div><div className="completion-score"><strong>{completion?.score??0}%</strong><span>{completion?.complete?'릴리스 가능':'릴리스 준비도'}</span></div>{Object.entries(completion?.checks||{}).map(([k,v])=><div className="check-row" key={k}><span className={v?'pass':'wait'}>{v?<Check size={12}/>:<Timer size={12}/>}</span><b>{{requirements:'필수 요구사항',safety:'중대 안전 위반 0건',simulation:'고정밀 시뮬레이션',manufacturing:'제조 가능성',physical:'필수 물리 시험',traceability:'완전 추적성',approval:'책임자 승인'}[k]}</b><em>{v?'충족':'대기'}</em></div>)}</aside></div>}
  </div>
}

export function GovernanceCenter({notify,projectId}){
  const[approvals,setApprovals]=useState([]),[notices,setNotices]=useState([]),[evaluation,setEvaluation]=useState(null),[design,setDesign]=useState(null),[compliance,setCompliance]=useState(null),[tab,setTab]=useState('승인 게이트');
  const load=()=>Promise.all([api.approvals(),api.notifications(true),api.graph(projectId),api.complianceAssessments(projectId)]).then(([a,n,g,c])=>{setApprovals(a.filter(x=>x.projectId===projectId));setNotices(n.filter(x=>!x.data?.projectId||x.data.projectId===projectId));const next=g.designs?.at(-1)||null;setDesign(next);setCompliance(c.find(x=>x.designId===next?.id)||null)}).catch(()=>{});useEffect(()=>{if(projectId){setEvaluation(null);setCompliance(null);load()}},[projectId]);
  const decide=(id,status)=>api.decideApproval(id,status,'운영 관리자 검토').then(()=>{notify(status==='approved'?'승인 결정을 기록했습니다':'변경을 반려했습니다');load()}).catch(e=>notify(`승인 처리 불가 · ${e.message}`));
  const assess=()=>design?api.assessCompliance(projectId,design.id).then(x=>{setCompliance(x);notify(x.compliant?'내부 사전 적합성 통과':'사전 적합성 미충족 · 증거를 확인하세요')}).catch(e=>notify(`판정 실행 불가 · ${e.message}`)):notify('평가할 설계가 없습니다');
  return <div className="governance-center"><section className="governance-hero"><div><span>SAFETY GOVERNANCE</span><h1>모든 실행에 안전을 내재화.</h1><p>입력부터 설계, 시뮬레이션, 로봇, 릴리스까지 독립 검토와 증거를 강제합니다.</p></div><div className="safety-score"><strong>{compliance?.criticalFailures??'—'}</strong><span>중대 통제 미충족<br/><em>{compliance?compliance.policyVersion:'평가 전'}</em></span><ShieldCheck size={28}/></div></section><div className="mission-tabs">{['승인 게이트','규정 매트릭스','안전 방어선','제조·공급 위험'].map(x=><button key={x} className={tab===x?'active':''} onClick={()=>setTab(x)}>{x}</button>)}<span className="notice-count"><Bell size={13}/>{notices.length} unread</span></div>
  {tab==='승인 게이트'&&<div className="approval-layout"><section className="panel approval-list"><div className="panel-title"><div><UserCheck size={15}/><h3>검토 대기</h3><span className="count">{approvals.filter(x=>x.status==='pending').length}</span></div></div>{approvals.length?approvals.map(a=><div className="approval-row" key={a.id}><span className={`grade ${a.grade}`}>{a.grade}</span><div><b>{a.title}</b><small>{a.kind} · 증거 {a.evidence?.length||0}개 · {a.progress.received}/{a.progress.required} 승인</small></div><em className={a.status}>{a.status}</em>{a.status==='pending'&&<div><button onClick={()=>decide(a.id,'rejected')}>반려</button><button onClick={()=>decide(a.id,'approved')} className="approve">승인</button></div>}</div>):<div className="empty-state"><ShieldCheck size={30}/><b>대기 중인 승인 없음</b><span>새 고위험 변경이 요청되면 여기에 표시됩니다.</span></div>}</section><aside className="panel notification-list"><div className="panel-title"><div><Bell size={15}/><h3>운영 알림</h3></div></div>{notices.length?notices.slice(0,6).map(n=><button key={n.id} onClick={()=>api.markNotification(n.id).then(load)}><i className={n.severity}/><div><b>{n.title}</b><small>{n.message}</small></div></button>):<div className="empty-state small"><Bell size={22}/><span>읽지 않은 알림이 없습니다.</span></div>}</aside></div>}
  {tab==='규정 매트릭스'&&<section className="panel compliance-matrix"><div className="panel-title"><div><ShieldCheck size={15}/><h3>내부 사전 적합성 · {design?.id||'설계 없음'}</h3></div><Button primary onClick={assess}><Play size={13}/>증거 재평가</Button></div><div className="compliance-notice"><AlertTriangle size={14}/>{compliance?.notice||'AutoForge 내부 사전 적합성 평가이며 공인 인증 또는 법적 적합성 인증을 대체하지 않습니다.'}</div>{compliance?<><div className="compliance-summary"><strong className={compliance.compliant?'pass':'fail'}>{compliance.compliant?'PASS':'HOLD'}</strong><span>{compliance.summary.pass}/{compliance.summary.total} 통과</span><span>{compliance.summary.fail} 실패</span><span>{compliance.summary.unverified} 미검증</span><code>{compliance.sha256?.slice(0,16)}…</code></div>{compliance.rules.map(r=><div className={`compliance-rule ${r.status}`} key={r.id}><span>{r.id}<small>{r.severity}</small></span><div><b>{r.title}</b><small>기준 {r.threshold} · 실제 {r.actual??'증거 없음'}</small><em>증거 {r.evidenceIds.length?r.evidenceIds.join(' · '):'없음'}</em></div><strong>{r.status}</strong></div>)}</>:<div className="empty-state"><ShieldCheck size={30}/><b>판정 이력 없음</b><span>현재 설계의 실제 증거로 내부 사전 적합성을 평가하세요.</span></div>}</section>}
  {tab==='안전 방어선'&&<div className="defense-grid">{[['01','입력 통제','위험 목표와 명령 차단','ACTIVE'],['02','설계 규칙','금지 소재·치수 차단','ACTIVE'],['03','시뮬레이션','안전 한계 초과 탐지','ACTIVE'],['04','독립 리뷰','생성과 심사 권한 분리','ACTIVE'],['05','인간 승인','S0–S5 정족수 적용','ACTIVE'],['06','물리 인터록','로봇 셀 강제 정지','ACTIVE'],['07','운영 감시','이상 징후와 실패율 추적','ACTIVE'],['08','감사 추적','모든 판단과 변경 기록','ACTIVE']].map(x=><div key={x[0]}><span>{x[0]}</span><ShieldCheck size={18}/><b>{x[1]}</b><p>{x[2]}</p><em>{x[3]}</em></div>)}</div>}
  {tab==='제조·공급 위험'&&<div className="manufacturing-view"><section className="panel"><div className="panel-title"><div><Factory size={15}/><h3>제조 가능성 평가</h3></div><Button primary onClick={()=>design?api.manufacturingEvaluate({projectId,designId:design.id,parameters:design.parameters}).then(x=>{setEvaluation(x);notify('BOM·DFM·공급망 평가 완료')}):notify('평가할 설계를 먼저 생성하세요')}><Play size={13}/>평가 실행</Button></div>{evaluation?<><div className="mfg-score"><strong>{evaluation.manufacturable?'PASS':'HOLD'}</strong><span>총 제조원가 <b>₩ {(evaluation.cost.total/1000000).toFixed(2)}M</b></span><span>공급 위험 <b>{evaluation.supplyRiskScore}/100</b></span><span>조립 스테이션 <b>{evaluation.assembly.stations}</b></span></div>{evaluation.issues.map((x,i)=><div className="risk-row" key={i}><AlertTriangle size={14}/><span><b>{x.code}</b><small>{x.partNo||'Vehicle architecture'}</small></span><em>{x.severity}</em></div>)}</>:<div className="empty-state"><Factory size={30}/><b>{design?`${design.id} 평가 대기`:'설계 후보 없음'}</b><span>BOM, DFM 규칙과 공급사 위험을 동시에 검사합니다.</span></div>}</section></div>}
  </div>
}

export function PlatformOps({notify}){
  const[runs,setRuns]=useState([]),[releases,setReleases]=useState([]),[selected,setSelected]=useState(null),[mcp,setMcp]=useState(null);const load=()=>Promise.all([api.improvements(),api.releases(),api.mcpTools()]).then(([r,x,g])=>{setRuns(r);setReleases(x);setMcp(g);if(!selected&&r[0])setSelected(r[0])}).catch(()=>{});useEffect(()=>{load()},[]);const steps=['draft','reviewed','tested','benchmarked','security_verified','approval_pending','approved','canary','deployed'];
  return <div className="platform-ops"><section className="module-banner"><div><span>PLATFORM SELF-IMPROVEMENT</span><h1>개선은 자동으로, 배포는 통제 아래.</h1><p>운영 실패를 코드 변경으로 전환하고 독립 검증·카나리·롤백까지 추적합니다.</p></div><Button><Activity size={14}/>시스템 정상</Button></section><div className="ops-kpis"><div><small>활성 개선</small><b>{runs.filter(x=>!['deployed','rolled_back','failed'].includes(x.status)).length}</b><em>격리 실행</em></div><div><small>MCP 도구</small><b>{mcp?.tools.length||0}</b><em>{mcp?.protocolVersion||'loading'}</em></div><div><small>자동 롤백</small><b>{runs.filter(x=>x.status==='rolled_back').length}</b><em>성능 보호</em></div><div><small>현재 릴리스</small><b>v0.8.14</b><em>{releases.length} tracked</em></div></div><div className="ops-layout"><section className="panel improvement-list"><div className="panel-title"><div><Workflow size={15}/><h3>개선 파이프라인</h3></div><span className="count">{runs.length}</span></div>{runs.length?runs.map(r=><button className={selected?.id===r.id?'active':''} onClick={()=>setSelected(r)} key={r.id}><span className={`risk ${r.riskGrade}`}>{r.riskGrade}</span><div><b>{r.title}</b><small>{r.type} · {r.status}</small></div><em>{r.status}</em><ChevronRight size={14}/></button>):<div className="empty-state"><Cpu size={30}/><b>현재 개선 실행 없음</b><span>운영 이슈가 감지되면 격리 파이프라인이 생성됩니다.</span></div>}</section><aside className="panel pipeline-detail"><div className="panel-title"><div><ShieldCheck size={15}/><h3>품질 게이트</h3></div></div>{selected?<><div className="change-title"><span>{selected.riskGrade}</span><div><b>{selected.title}</b><small>{selected.id}</small></div></div><div className="pipeline-steps">{steps.map((s,i)=>{const current=steps.indexOf(selected.status),done=current>=i||selected.status==='deployed';return <div className={`${done?'done':''} ${selected.status===s?'current':''}`} key={s}><span>{done?<Check size={11}/>:i+1}</span><b>{{draft:'격리 브랜치',reviewed:'독립 리뷰',tested:'자동 테스트',benchmarked:'성능 비교',security_verified:'보안 검증',approval_pending:'인간 승인',approved:'배포 승인',canary:'카나리',deployed:'전체 배포'}[s]}</b></div>})}</div>{selected.failure&&<div className="pipeline-failure"><AlertTriangle size={14}/><span><b>파이프라인 중단</b>{selected.failure.reason}</span></div>}{selected.canary&&<div className="canary-card"><span>CANARY {selected.canary.percent}%</span><b>{selected.canary.status}</b><em>{selected.canary.observations.length} observations</em></div>}</>:<div className="empty-state small"><Workflow size={24}/><span>개선 항목을 선택하세요.</span></div>}</aside></div><section className="panel mcp-registry"><div className="panel-title"><div><Cpu size={15}/><h3>MCP Engineering Gateway</h3><span className="count">{mcp?.endpoint||'/mcp'}</span></div><em>{mcp?.protocolVersion}</em></div><div className="mcp-tools">{mcp?.tools.map(tool=><div key={tool.name}><span className={tool.annotations?.destructiveHint?'danger':'safe'}>{tool.annotations?.readOnlyHint?'READ':tool.annotations?.destructiveHint?'S4 GATE':'WRITE'}</span><div><b>{tool.title}</b><code>{tool.name}</code><small>{tool.description}</small></div></div>)}</div></section></div>
}
export function AgentCenter({notify}){
  const[agents,setAgents]=useState([]),[catalog,setCatalog]=useState({roles:[],tools:[],models:[]}),[selectedId,setSelectedId]=useState(''),[draft,setDraft]=useState(null),[creating,setCreating]=useState(false),[busy,setBusy]=useState(false);
  const load=()=>Promise.all([api.agents(),api.agentCatalog()]).then(([a,c])=>{setAgents(a);setCatalog(c);setSelectedId(current=>a.some(x=>x.id===current)?current:a[0]?.id||'')}).catch(e=>notify(`에이전트 레지스트리 연결 실패 · ${e.message}`));useEffect(()=>{load()},[]);useEffect(()=>{const agent=agents.find(x=>x.id===selectedId);if(agent){setDraft({...agent,tools:[...(agent.tools||[])]});setCreating(false)}},[selectedId,agents]);
  const newAgent=()=>{setCreating(true);setSelectedId('');setDraft({name:'',role:'style',modelRef:catalog.models[0]||'engineering-agent-v1',promptVersion:'1.0.0',tools:['design.graph'],canGenerate:true,canReview:false,enabled:true})};
  const toggleTool=tool=>setDraft(x=>({...x,tools:x.tools.includes(tool)?x.tools.filter(t=>t!==tool):[...x.tools,tool]}));
  const save=async()=>{if(!draft)return;setBusy(true);try{const result=creating?await api.createAgent(draft):await api.updateAgent(draft.id,{name:draft.name,role:draft.role,modelRef:draft.modelRef,promptVersion:draft.promptVersion,tools:draft.tools,canGenerate:draft.canGenerate,canReview:draft.canReview,enabled:draft.enabled});notify(`${result.name} 에이전트 정책을 ${creating?'생성':'갱신'}했습니다`);setCreating(false);await load();setSelectedId(result.id)}catch(e){notify(`에이전트 정책 저장 실패 · ${e.message}`)}finally{setBusy(false)}};
  const enabled=agents.filter(x=>x.enabled!==false).length,reviewers=agents.filter(x=>x.canReview).length,toolCount=new Set(agents.flatMap(x=>x.tools||[])).size;
  return <div className="agent-center"><section className="module-banner"><div><span>AGENT GOVERNANCE</span><h1>전문성은 분리하고, 권한은 최소화.</h1><p>조직의 자동차 엔지니어링 에이전트 역할·모델·프롬프트·허용 도구와 생성/심사 분리를 통제합니다.</p></div><Button primary onClick={newAgent}><Plus size={14}/>전문 에이전트 추가</Button></section><div className="agent-kpis"><div><small>등록 에이전트</small><b>{agents.length}</b><em>{enabled} enabled</em></div><div><small>독립 심사자</small><b>{reviewers}</b><em>생성 권한 분리</em></div><div><small>할당 도구</small><b>{toolCount}</b><em>{catalog.tools.length} allowlisted</em></div><div><small>모델 정책</small><b>{catalog.models.length}</b><em>registry references</em></div></div><div className="agent-registry-layout"><section className="panel agent-registry-list"><div className="panel-title"><div><Cpu size={15}/><h3>조직 에이전트</h3><span className="count">{agents.length}</span></div></div>{agents.map(agent=><button key={agent.id} onClick={()=>setSelectedId(agent.id)} className={selectedId===agent.id?'active':''}><span className={`${agent.enabled===false?'disabled':agent.status}`}><Cpu size={15}/></span><div><b>{agent.name}</b><small>{agent.role} · {agent.modelRef}</small></div><em>{agent.canReview?'REVIEW':agent.canGenerate?'GENERATE':'EVIDENCE'}</em><i>{agent.tools?.length||0}</i></button>)}</section><section className="panel agent-policy-editor"><div className="panel-title"><div><ShieldCheck size={15}/><h3>{creating?'새 최소권한 정책':'에이전트 정책 편집'}</h3></div>{draft&&<span className={`agent-enabled ${draft.enabled?'on':'off'}`}>{draft.enabled?'ENABLED':'DISABLED'}</span>}</div>{draft?<><div className="agent-policy-fields"><label><span>표시 이름</span><input value={draft.name} onChange={e=>setDraft(x=>({...x,name:e.target.value}))}/></label><label><span>전문 역할</span><select value={draft.role} onChange={e=>setDraft(x=>({...x,role:e.target.value}))}>{catalog.roles.map(x=><option key={x}>{x}</option>)}</select></label><label><span>모델 참조</span><select value={draft.modelRef} onChange={e=>setDraft(x=>({...x,modelRef:e.target.value}))}>{catalog.models.map(x=><option key={x}>{x}</option>)}</select></label><label><span>프롬프트 버전</span><input value={draft.promptVersion} onChange={e=>setDraft(x=>({...x,promptVersion:e.target.value}))}/></label></div><div className="duty-separation"><button className={draft.canGenerate?'active':''} onClick={()=>setDraft(x=>({...x,canGenerate:!x.canGenerate,canReview:x.canGenerate?x.canReview:false}))}><Sparkles size={13}/><span><b>설계 생성자</b><small>후보와 개선안 생성</small></span></button><button className={draft.canReview?'active':''} onClick={()=>setDraft(x=>({...x,canReview:!x.canReview,canGenerate:x.canReview?x.canGenerate:false}))}><ShieldCheck size={13}/><span><b>독립 심사자</b><small>자신의 설계 승인 불가</small></span></button><button className={draft.enabled?'active':''} onClick={()=>setDraft(x=>({...x,enabled:!x.enabled}))}><Activity size={13}/><span><b>런타임 활성</b><small>오케스트레이터 배정 허용</small></span></button></div><div className="agent-tool-policy"><b>허용 MCP·엔지니어링 도구</b><small>목록 밖 도구는 서버에서 거부됩니다.</small><div>{catalog.tools.map(tool=><button onClick={()=>toggleTool(tool)} className={draft.tools.includes(tool)?'active':''} key={tool}><span>{draft.tools.includes(tool)?<Check size={10}/>:<Plus size={10}/>}</span>{tool}</button>)}</div></div><div className="agent-policy-actions"><span><Lock size={12}/>생성과 심사 권한은 동시에 부여할 수 없습니다.</span><Button primary onClick={save}><Save size={13}/>{busy?'정책 검증 중…':'정책 저장'}</Button></div></>:<div className="empty-state"><Cpu size={28}/><span>에이전트를 선택하거나 새 정책을 만드세요.</span></div>}</section></div></div>
}
function GoalBranch({goal,children,depth=0}){const kids=children(goal.id);return <div className="goal-branch"><div className={`goal-node ${goal.level} ${goal.status}`} style={{marginLeft:depth*28}}><span>{goal.level}</span><div><b>{goal.name}</b><small>{goal.id}{goal.target!==undefined?` · 목표 ${goal.target}${goal.unit}`:''}</small></div>{goal.actual!==undefined&&<em>{goal.actual}{goal.unit}</em>}<i>{goal.status==='pass'?<Check size={12}/>:goal.status==='at_risk'?<AlertTriangle size={12}/>:<Activity size={12}/>}</i></div>{kids.map(k=><GoalBranch key={k.id} goal={k} children={children} depth={depth+1}/>)}</div>}

export function ConceptLab({ notify, projectId }) {
  const [view, setView] = useState('3/4');
  const [panel, setPanel] = useState('프로포션');
  const [params, setParams] = useState({ length:3990, wheelbase:2630, height:1570, wheel:19, roof:42, stance:58 });
  const [hotspots, setHotspots] = useState(true);
  const [variants,setVariants]=useState([]),[variantBusy,setVariantBusy]=useState(false);
  const update = (key, value) => setParams(p => ({...p, [key]: Number(value)}));
  const [specs,setSpecs] = useState({range:418,cd:'0.231',room:92});
  const [activeDesign,setActiveDesign]=useState(null);
  useEffect(()=>{if(projectId)api.graph(projectId).then(g=>{const generated=(g.designs||[]).filter(x=>x.status==='concept_variant').slice(-6),d=(g.designs||[]).at(-1);setVariants(generated);setActiveDesign(d||null);if(d?.parameters)setParams(p=>({...p,...d.parameters}))}).catch(()=>{})},[projectId]);
  const explore=async()=>{if(!activeDesign)return notify('먼저 현재 파라미터로 CAD 설계를 생성하세요');setVariantBusy(true);try{const result=await api.generateVariants(activeDesign.id,6);setVariants(result.variants);notify(`${activeDesign.id}에서 6개 설계 철학 변형을 생성했습니다`)}catch(e){notify(`변형 생성 실패 · ${e.message}`)}finally{setVariantBusy(false)}};
  const chooseVariant=variant=>{setActiveDesign(variant);setParams(p=>({...p,...variant.parameters}));notify(`${variant.name} · ${variant.metrics.range}km · ${variant.metrics.cost}M 선택`)};
  useEffect(()=>{const timer=setTimeout(()=>api.estimate(params).then(m=>setSpecs({range:m.range,cd:m.cd,room:Math.round(92+(params.wheelbase-2630)*.035)})).catch(()=>{}),180);return()=>clearTimeout(timer)},[params]);
  const localSpecs = useMemo(() => ({
    range: Math.round(418 - (params.wheel-19)*7 - (params.height-1570)*.018),
    cd: (0.231 + (params.height-1570)*.000035 + (params.stance-58)*.0003).toFixed(3),
    room: Math.round(92 + (params.wheelbase-2630)*.035)
  }), [params]);
  return <div className="visual-studio">
    <div className="studio-toolbar">
      <div className="tool-title"><span>CONCEPT / {activeDesign?.id||'NEW'}</span><b>{activeDesign?.name||'새 시각 설계'}</b><em>{activeDesign?'프로젝트와 동기화됨':'첫 설계 대기'}</em></div>
      <div className="history-tools"><button title="저장 설계 복원" onClick={()=>activeDesign?.parameters&&setParams(p=>({...p,...activeDesign.parameters}))}><RotateCcw size={15}/></button><button title="비교"><GitCompare size={15}/></button><i/><button onClick={()=>setHotspots(!hotspots)} className={hotspots?'active':''}><Eye size={15}/>인사이트</button><Button onClick={()=>api.createDesign({projectId,name:'Visual Snapshot',parameters:params}).then(d=>api.generateCad(d.id).then(result=>{setActiveDesign(d);notify(`${d.id} · ${result.artifacts.length}개 CAD 산출물을 생성했습니다`)})).catch(()=>notify('CAD 생성 API를 확인하세요'))}><Save size={14}/>CAD 생성</Button><Button primary onClick={explore}><Sparkles size={14}/>{variantBusy?'6개 탐색 중…':'6개 변형 탐색'}</Button></div>
    </div>
    <div className="studio-layout">
      <aside className="design-tree">
        <div className="tree-head"><b>디자인 레이어</b><button><Plus size={14}/></button></div>
        {[
          ['Exterior surfaces', Layers3, true],['Glass canopy', Hexagon, true],['Front signature', Zap, true],['Wheel package', Gauge, true],['Aero elements', Wind, false]
        ].map(([x,I,on],i)=><button className={i===0?'selected':''} key={x}><I size={14}/><span>{x}</span><Eye size={13} className={on?'':'dim'}/><Lock size={11}/></button>)}
        <div className="variant-head"><b>실제 디자인 변형</b><span>{String(variants.length).padStart(2,'0')}</span></div>
        {variants.length?variants.map((x,i)=><button onClick={()=>chooseVariant(x)} className={`variant-row ${activeDesign?.id===x.id?'selected':''}`} key={x.id}><i style={{background:['#c7d0d2','#72909d','#c6c0b6','#788b71','#d2a680','#889ba5'][i]}}/><span>{x.name}</span>{activeDesign?.id===x.id&&<Check size={12}/>}</button>):<div className="variant-empty">현재 설계에서 변형 탐색을 실행하세요.</div>}
      </aside>
      <main className="design-canvas">
        <div className="canvas-grid"/>
        <div className={`car-stage view-${view.replace('/','')}`}><img src="/assets/urban-ev-concept.png" alt="편집 중인 Urban Flow 전기차"/></div>
        {hotspots && <div className="hotspots">
          <button className="hotspot h1"><span>01</span><div><b>A필러 곡률</b><small>Cd −0.006 가능</small></div></button>
          <button className="hotspot h2"><span>02</span><div><b>휠 아치 간격</b><small>현가 여유 +8 mm</small></div></button>
          <button className="hotspot h3"><span>03</span><div><b>후방 시계</b><small>규정 경계 2.4°</small></div></button>
        </div>}
        <div className="view-cube"><span>TOP</span><b>FRONT</b><i>R</i></div>
        <div className="canvas-bottom">
          <div className="view-tabs">{['3/4','측면','전면','후면','탑'].map(v=><button className={view===v?'active':''} onClick={()=>setView(v)} key={v}>{v}</button>)}</div>
          <div className="canvas-tools"><button><Minus size={14}/></button><span>72%</span><button><Plus size={14}/></button><button><Maximize2 size={14}/></button></div>
        </div>
        <div className="dimension dim-length"><i/><span>{params.length} mm</span><i/></div>
        <div className="dimension dim-height"><i/><span>{params.height} mm</span><i/></div>
      </main>
      <aside className="parameter-panel">
        <div className="parameter-head"><b>디자인 파라미터</b><SlidersHorizontal size={15}/></div>
        <div className="param-tabs">{['프로포션','표면','CMF'].map(x=><button key={x} className={panel===x?'active':''} onClick={()=>setPanel(x)}>{x}</button>)}</div>
        {panel==='프로포션' ? <div className="params">
          <Parameter label="전장" value={params.length} min={3800} max={4100} unit="mm" onChange={v=>update('length',v)}/>
          <Parameter label="휠베이스" value={params.wheelbase} min={2500} max={2800} unit="mm" onChange={v=>update('wheelbase',v)}/>
          <Parameter label="전고" value={params.height} min={1450} max={1680} unit="mm" onChange={v=>update('height',v)}/>
          <Parameter label="휠 직경" value={params.wheel} min={17} max={21} unit="in" onChange={v=>update('wheel',v)}/>
          <Parameter label="루프 아크" value={params.roof} min={20} max={80} unit="%" onChange={v=>update('roof',v)}/>
          <Parameter label="스탠스" value={params.stance} min={20} max={90} unit="%" onChange={v=>update('stance',v)}/>
        </div> : panel==='표면' ? <SurfacePanel/> : <CMFPanel/>}
        <div className="live-impact"><div><Sparkles size={14}/><b>실시간 영향 예측 · API</b></div><span><small>예상 주행거리</small><b>{specs.range||localSpecs.range} km</b></span><span><small>예상 Cd</small><b>{specs.cd||localSpecs.cd}</b></span><span><small>실내 공간 지수</small><b>{specs.room||localSpecs.room}</b></span></div>
      </aside>
    </div>
  </div>
}

function Parameter({label,value,min,max,unit,onChange}) { return <label className="parameter"><span><b>{label}</b><em>{value} {unit}</em></span><input type="range" value={value} min={min} max={max} onChange={e=>onChange(e.target.value)}/><small><i>{min}</i><i>{max}</i></small></label> }
function SurfacePanel(){return <div className="option-panel"><label><span>곡면 연속성</span><select><option>Class A · G2</option><option>G1</option></select></label><label><span>캐릭터 라인 강도</span><input type="range" defaultValue="44"/></label><label><span>숄더 볼륨</span><input type="range" defaultValue="62"/></label><label><span>패널 갭</span><select><option>3.2 mm</option><option>3.5 mm</option></select></label></div>}
function CMFPanel(){return <div className="cmf-panel"><b>바디 컬러</b><div>{['#c8cfd0','#151b1e','#7e8b7a','#9c8069','#e8e4da'].map((c,i)=><button aria-label={`바디 컬러 ${c}`} key={c} className={i===0?'active':''} style={{background:c}}/> )}</div><b>하부 트림</b><div>{['#171b1d','#343b3e','#667176'].map(c=><button aria-label={`하부 트림 컬러 ${c}`} key={c} style={{background:c}}/>)}</div><label><span>소재</span><select><option>재생 무광 폴리머</option><option>알루미늄</option></select></label></div>}

const initialNodes = [
  {id:'vcu',x:43,y:12,title:'Vehicle Control',sub:'VCU · ASIL-D',type:'control'},
  {id:'battery',x:12,y:40,title:'Battery Pack',sub:'78.4 kWh · 400V',type:'energy'},
  {id:'motor',x:43,y:40,title:'E-Axle',sub:'160 kW · FWD',type:'drive'},
  {id:'thermal',x:73,y:40,title:'Thermal Loop',sub:'3-way heat pump',type:'thermal'},
  {id:'adas',x:18,y:70,title:'ADAS Domain',sub:'L2+ · 12 sensors',type:'control'},
  {id:'body',x:48,y:70,title:'Body & Chassis',sub:'Steel / Al hybrid',type:'body'},
  {id:'charge',x:76,y:70,title:'Charging',sub:'180 kW DC',type:'energy'},
];
const links=[['vcu','battery'],['vcu','motor'],['vcu','thermal'],['battery','motor'],['battery','thermal'],['vcu','adas'],['vcu','body'],['battery','charge'],['thermal','body']];

export function ArchitectureDesigner({notify,projectId}){
  const [nodes,setNodes]=useState(initialNodes),[graphLinks,setGraphLinks]=useState(links),[selected,setSelected]=useState('motor'),[revision,setRevision]=useState(null),[dirty,setDirty]=useState(false),[saving,setSaving]=useState(false); const board=useRef(null);
  useEffect(()=>{if(!projectId)return;setRevision(null);setNodes(initialNodes);setGraphLinks(links);setSelected('motor');setDirty(false);api.architectures(projectId).then(items=>{if(items[0]){setRevision(items[0]);setNodes(items[0].nodes);setGraphLinks(items[0].links.map(x=>[x.from,x.to]));setSelected(items[0].nodes[0]?.id)}}).catch(e=>notify(`아키텍처 계보 연결 실패 · ${e.message}`))},[projectId]);
  const drag=(e,id)=>{e.preventDefault();const rect=board.current.getBoundingClientRect();const move=ev=>{setDirty(true);setNodes(ns=>ns.map(n=>n.id===id?{...n,x:Math.max(3,Math.min(86,(ev.clientX-rect.left)/rect.width*100-7)),y:Math.max(5,Math.min(84,(ev.clientY-rect.top)/rect.height*100-4))}:n))};const up=()=>{window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up)};window.addEventListener('mousemove',move);window.addEventListener('mouseup',up)};
  const moveNode=(e,id)=>{const delta={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]}[e.key];if(!delta)return;e.preventDefault();setDirty(true);setNodes(ns=>ns.map(n=>n.id===id?{...n,x:Math.max(3,Math.min(86,n.x+delta[0])),y:Math.max(5,Math.min(84,n.y+delta[1]))}:n))};
  const reset=()=>{setNodes(revision?.nodes||initialNodes);setGraphLinks(revision?.links?.map(x=>[x.from,x.to])||links);setSelected((revision?.nodes||initialNodes)[0].id);setDirty(false)};
  const save=async()=>{setSaving(true);try{const item=await api.saveArchitecture({projectId,name:'EV Skateboard Architecture',nodes,links:graphLinks.map(([from,to])=>({from,to,interface:'vehicle_bus'}))});setRevision(item);setDirty(false);notify(`아키텍처 Rev ${item.revision} 저장 · SHA ${item.sha256.slice(0,8)} · ${item.valid?'필수 도메인 통과':`${item.issues.length}개 문제`}`)}catch(e){notify(`아키텍처 저장 실패 · ${e.message}`)}finally{setSaving(false)}};
  const addNode=(type,title)=>{const id=`${type}-${Date.now().toString(36)}`,node={id,x:70,y:16+nodes.length%5*14,title,sub:'New component',type,interfaces:['vehicle_bus']};setNodes(x=>[...x,node]);if(selected)setGraphLinks(x=>[...x,[selected,id]]);setSelected(id);setDirty(true)};
  const map=Object.fromEntries(nodes.map(n=>[n.id,n]));
  return <div className="arch-studio">
    <div className="studio-toolbar"><div className="tool-title"><span>VEHICLE ARCHITECTURE</span><b>EV Skateboard · Rev {revision?.revision||0}</b><em className={dirty?'dirty':''}>{dirty?'저장되지 않은 변경':revision?`SHA ${revision.sha256.slice(0,8)} · 동기화됨`:'최초 revision 대기'}</em></div><div className="history-tools"><Button onClick={reset}><RotateCcw size={14}/>저장본 복원</Button><Button primary onClick={save}><Save size={14}/>{saving?'검증·저장 중…':'새 Revision 저장'}</Button></div></div>
    <div className="arch-layout">
      <aside className="component-lib"><div className="tree-head"><b>컴포넌트 라이브러리</b><Plus size={14}/></div><div className="lib-search"><Search size={13}/><input placeholder="부품 검색"/></div>{[['ENERGY','energy',BatteryCharging,['Battery pack','On-board charger','DC/DC converter']],['DRIVE','drive',Zap,['E-Axle','Inverter','Reducer']],['CONTROL','control',Cpu,['Domain controller','ECU','Gateway']],['CHASSIS','body',Gauge,['Suspension','Brake system','Steering']]].map(([g,type,I,items])=><div className="lib-group" key={g}><span><I size={12}/>{g}</span>{items.map(x=><button onClick={()=>addNode(type,x)} key={x}><GripVertical size={12}/><i/><b>{x}</b><Plus size={12}/></button>)}</div>)}</aside>
      <main className="arch-board" ref={board} aria-label="차량 시스템 아키텍처 편집 캔버스"><div className="canvas-grid"/><div className="arch-note">블록을 이동하거나 라이브러리에서 선택해 연결된 컴포넌트를 추가하세요</div><svg className="connections" aria-hidden="true">{graphLinks.filter(([a,b])=>map[a]&&map[b]).map(([a,b])=><line key={a+b} x1={`${map[a].x+7}%`} y1={`${map[a].y+5}%`} x2={`${map[b].x+7}%`} y2={`${map[b].y+5}%`}/>)}</svg>{nodes.map(n=><button key={n.id} onMouseDown={e=>drag(e,n.id)} onKeyDown={e=>moveNode(e,n.id)} onClick={()=>setSelected(n.id)} aria-label={`${n.title}, ${n.sub}. 방향키로 이동`} style={{left:`${n.x}%`,top:`${n.y}%`}} className={`arch-node ${n.type} ${selected===n.id?'selected':''}`}><span><NodeIcon type={n.type}/></span><div><b>{n.title}</b><small>{n.sub}</small></div><i/></button>)}<div className="arch-legend"><span><i className="energy"/>에너지</span><span><i className="drive"/>구동</span><span><i className="control"/>제어</span><span><i className="thermal"/>열</span></div></main>
      <aside className="node-inspector"><div className="parameter-head"><b>컴포넌트 속성</b><Wrench size={14}/></div>{map[selected]?<><div className="node-title"><span><NodeIcon type={map[selected].type}/></span><div><b>{map[selected].title}</b><small>{map[selected].sub}</small></div></div><div className="property-list"><label><span>그래프 상태</span><em className={revision?.valid?'ok':''}>{revision?.valid?'필수 도메인 통과':'저장 검증 전'}</em></label><label><span>설계 Revision</span><b>Rev {revision?.revision||0}</b></label><label><span>연결 인터페이스</span><b>{graphLinks.filter(x=>x.includes(selected)).length} LINKS</b></label><label><span>무결성 해시</span><b>{revision?.sha256?.slice(0,12)||'—'}</b></label></div><div className="constraint-card"><span><ShieldCheck size={14}/>그래프 검증</span><p>Control · Energy · Drive 필수</p><p>고아 컴포넌트와 잘못된 링크 탐지</p><p>모든 revision과 부모 계보 보존</p></div>{revision?.issues?.map(x=><div className="arch-issue" key={`${x.code}-${x.nodeId||''}`}><AlertTriangle size={11}/>{x.code}</div>)}</>:<div className="empty-state small"><Layers3 size={24}/><span>컴포넌트를 선택하세요.</span></div>}</aside>
    </div>
  </div>
}
function NodeIcon({type}){const I={energy:BatteryCharging,drive:Zap,control:Cpu,thermal:Thermometer,body:Hexagon}[type]||Box;return <I size={16}/>}

export function OptimizationCenter({notify,projectId}){
 const [objective,setObjective]=useState('균형'),[run,setRun]=useState(null),[selected,setSelected]=useState(null),[designs,setDesigns]=useState([]),[designId,setDesignId]=useState(''),[busy,setBusy]=useState(false);const profiles={균형:{range:.35,cost:.3,weight:.2,space:.15},주행거리:{range:.7,cost:.15,weight:.1,space:.05},'최저 원가':{range:.15,cost:.7,weight:.1,space:.05}};useEffect(()=>{if(!projectId)return;setRun(null);setSelected(null);Promise.all([api.optimizations(projectId),api.graph(projectId)]).then(([items,g])=>{setDesigns(g.designs||[]);setDesignId(g.designs?.at(-1)?.id||'');if(items[0]){setRun(items[0]);setSelected(items[0].candidates.find(x=>x.id===items[0].recommendedCandidateId))}}).catch(()=>{})},[projectId]);const execute=async()=>{if(!designId)return notify('최적화할 설계 후보가 필요합니다');setBusy(true);try{const result=await api.optimize({projectId,designId,weights:profiles[objective],seed:42});setRun(result);setSelected(result.candidates.find(x=>x.id===result.recommendedCandidateId));notify(`${result.candidateCount}개 후보 · Pareto ${result.paretoCount}개 생성`)}catch(error){notify(`최적화 실패 · ${error.message}`)}finally{setBusy(false)}};const dots=useMemo(()=>{if(!run)return[];const costs=run.candidates.map(x=>x.metrics.cost),ranges=run.candidates.map(x=>x.metrics.range),minC=Math.min(...costs),maxC=Math.max(...costs),minR=Math.min(...ranges),maxR=Math.max(...ranges);return run.candidates.map(x=>({...x,x:5+(x.metrics.cost-minC)/(maxC-minC||1)*88,y:5+(x.metrics.range-minR)/(maxR-minR||1)*84}))},[run]);const promote=()=>selected&&api.promoteOptimization(run.id,selected.id).then(d=>notify(`${d.id} 설계 버전으로 승격했습니다`)).catch(e=>notify(`승격 실패 · ${e.message}`));
 return <ModuleShell eyebrow="MULTI-OBJECTIVE OPTIMIZATION" title="정답 하나가 아닌, 최선의 선택지." desc="성능·원가·중량의 상충 관계를 탐색하고 설계 의사결정을 기록합니다." action={<div className="module-select-action"><select value={designId} onChange={e=>setDesignId(e.target.value)}>{designs.map(x=><option value={x.id} key={x.id}>{x.id} · {x.name}</option>)}</select><Button primary onClick={execute}><Play size={14}/>{busy?'탐색 중…':'250개 후보 최적화'}</Button></div>}>
   <div className="opt-layout"><section className="pareto panel"><div className="panel-title"><div><h3>파레토 프론티어</h3><span className="count">{run?`${run.candidateCount} candidates · ${run.paretoCount} Pareto`:'실행 대기'}</span></div><em>{run?.algorithm}</em></div><div className="plot"><span className="axis-y">주행거리 ↑</span><span className="axis-x">제조 원가 →</span><div className="gridlines"/>{dots.map(d=><button aria-label={`${d.id}, ${d.metrics.range} km, ${d.metrics.cost}M KRW`} title={`${d.id} · ${d.philosophy}`} onClick={()=>setSelected(d)} key={d.id} className={`${d.pareto?'frontier':''} ${selected?.id===d.id?'selected':''} ${d.feasible?'':'infeasible'}`} style={{left:`${d.x}%`,bottom:`${d.y}%`}}/>)}{selected&&<div className="plot-callout" style={{left:`${Math.min(76,dots.find(x=>x.id===selected.id)?.x||62)}%`,bottom:`${Math.min(80,(dots.find(x=>x.id===selected.id)?.y||58)+4)}%`}}><b>{selected.id} · {selected.score}</b><span>{selected.metrics.range} km · {selected.metrics.cost}M · {selected.metrics.weight}kg</span></div>}</div></section><aside className="objective panel"><div className="panel-title"><div><h3>목적함수와 후보 선택</h3></div></div>{['균형','주행거리','최저 원가'].map(x=><button className={objective===x?'active':''} onClick={()=>setObjective(x)} key={x}><span>{x}</span><em>{x==='균형'?'추천':''}</em></button>)}<Parameter label="주행거리" value={Math.round(profiles[objective].range*100)} min={0} max={100} unit="%" onChange={()=>{}}/><Parameter label="원가" value={Math.round(profiles[objective].cost*100)} min={0} max={100} unit="%" onChange={()=>{}}/><Parameter label="중량" value={Math.round(profiles[objective].weight*100)} min={0} max={100} unit="%" onChange={()=>{}}/><div className="constraint-card"><span><Check size={14}/>{run?`${run.feasibleCount}/${run.candidateCount} 필수 제약 통과`:'필수 제약 사전 적용'}</span><p>전장 ≤ 4,000 mm · 주행거리 ≥ 400 km</p><p>원가 ≤ 30M · 중량 ≤ 1,900 kg · Cd ≤ 0.250</p></div>{selected&&<div className="candidate-decision"><span>{selected.pareto?'PARETO':'CANDIDATE'} · {selected.philosophy}</span><b>{selected.id}</b><small>부모 {selected.parentDesignId} · 점수 {selected.score}</small><Button primary onClick={promote} className="promote-candidate">설계 버전으로 승격<ArrowUpRight size={12}/></Button></div>}</aside></div>
 </ModuleShell>
}

export function RobotLab({notify,projectId}){
  const[cells,setCells]=useState([]),[commands,setCommands]=useState([]),[approvals,setApprovals]=useState([]),[selectedCell,setSelectedCell]=useState(''),[action,setAction]=useState('robot.test');
  const load=()=>Promise.all([api.robotCells(),api.robotCommands(),api.approvals()]).then(([allCells,allCommands,a])=>{const c=allCells.filter(x=>x.projectId===projectId),m=allCommands.filter(x=>x.projectId===projectId);setCells(c);setCommands(m);setApprovals(a.filter(x=>x.grade==='S4'&&x.projectId===projectId));setSelectedCell(current=>c.some(x=>x.id===current)?current:c[0]?.id||'')}).catch(e=>notify(`로봇 게이트웨이 연결 실패 · ${e.message}`));useEffect(()=>{if(projectId)load()},[projectId]);
  const cell=cells.find(x=>x.id===selectedCell),approval=approvals.find(x=>x.status==='approved'&&x.targetId===selectedCell);
  const requestApproval=()=>cell&&api.createApproval({projectId:cell.projectId,grade:'S4',targetId:cell.id,kind:'robot_action',title:`${cell.name} ${action} 실행 승인`,evidence:Object.entries(cell.interlocks||{}).filter(([,v])=>v).map(([k])=>`INTERLOCK:${k}`)}).then(()=>{notify('S4 현장 책임자 승인을 요청했습니다');load()}).catch(e=>notify(`승인 요청 실패 · ${e.message}`));
  const dispatch=()=>{if(!cell)return;if(!approval)return notify('승인된 S4 요청이 필요합니다');api.robotAction({projectId:cell.projectId,cellId:cell.id,action,approvalId:approval.id,idempotencyKey:crypto.randomUUID(),parameters:{mode:'operator_confirmed'}}).then(x=>{notify(`${x.action} 명령이 안전 검사 후 전송됐습니다`);load()}).catch(e=>notify(`로봇 명령 차단 · ${e.message}`))};
  const stop=()=>cell&&window.confirm(`${cell.name}을 비상 정지합니까?`)&&api.robotEmergencyStop(cell.id).then(()=>{notify('비상정지 명령과 활성 작업 취소를 기록했습니다');load()}).catch(e=>notify(`비상정지 실패 · ${e.message}`));
  const restore=()=>cell&&api.robotInterlocks(cell.id,{emergencyStop:true,cellClear:true,guardClosed:true,sensorsHealthy:true}).then(()=>{notify('현장 인터록 확인을 기록했습니다');load()}).catch(e=>notify(`인터록 갱신 실패 · ${e.message}`));
  return <ModuleShell eyebrow="PHYSICAL VALIDATION" title="로봇 셀과 실제 시험을 연결." desc="S4 승인, 물리 인터록, 멱등 명령, 비상정지와 ROS 실행 확인을 하나의 안전 콘솔에서 관리합니다." action={<Button onClick={load}><RefreshCw size={14}/>게이트웨이 동기화</Button>}><div className="robot-live-layout"><section className="panel robot-cells"><div className="panel-title"><div><Bot size={15}/><h3>물리 로봇 셀</h3><span className="count">{cells.length}</span></div></div>{cells.map(c=><button key={c.id} onClick={()=>setSelectedCell(c.id)} className={`${selectedCell===c.id?'active':''} ${c.state}`}><span><Bot size={18}/><i/></span><div><b>{c.name}</b><small>{c.id} · {c.state}</small></div><em>{Object.values(c.interlocks||{}).filter(Boolean).length}/{Object.keys(c.interlocks||{}).length} SAFE</em></button>)}</section><section className="panel robot-control"><div className="panel-title"><div><ShieldCheck size={15}/><h3>승인·인터록 실행 게이트</h3></div><span className={`robot-gate ${approval?'pass':'wait'}`}>{approval?'S4 APPROVED':'S4 REQUIRED'}</span></div>{cell?<><div className="cell-state"><span><Bot size={28}/></span><div><b>{cell.name}</b><small>{cell.id} · {cell.state}</small></div><button className="emergency" onClick={stop}>EMERGENCY STOP</button></div><div className="interlock-grid">{Object.entries(cell.interlocks||{}).map(([k,v])=><div className={v?'safe':'unsafe'} key={k}><span>{v?<Check size={12}/>:<AlertTriangle size={12}/>}</span><b>{k}</b><em>{v?'SAFE':'OPEN'}</em></div>)}</div><div className="robot-action-form"><label><span>승인된 작업 유형</span><select value={action} onChange={e=>setAction(e.target.value)}><option value="robot.prototype">시제품 제작</option><option value="robot.test">반복 시험</option><option value="robot.inspect">치수·품질 검사</option><option value="robot.home">안전 원점 복귀</option></select></label>{cell.state==='emergency_stopped'?<Button primary onClick={restore}><ShieldCheck size={13}/>현장 인터록 복구 확인</Button>:approval?<Button primary onClick={dispatch}><Play size={13}/>안전 검사 후 명령 전송</Button>:<Button primary onClick={requestApproval}><Lock size={13}/>S4 실행 승인 요청</Button>}</div></>:<div className="empty-state"><Bot size={30}/><span>접근 가능한 로봇 셀이 없습니다.</span></div>}</section><aside className="panel robot-command-log"><div className="panel-title"><div><Activity size={15}/><h3>명령·ACK 이력</h3></div></div>{commands.length?commands.slice(0,8).map(c=><div className="robot-command" key={c.id}><i className={c.status}/><div><b>{c.action}</b><small>{c.cellId} · {c.id.slice(0,8)}</small></div><em>{c.status}</em>{c.status==='dispatched'&&<button onClick={()=>api.robotAck(c.id).then(()=>{notify('ROS 실행 완료 ACK를 기록했습니다');load()})}>완료 ACK</button>}</div>):<div className="empty-state small"><Activity size={24}/><span>명령 이력이 없습니다.</span></div>}</aside></div></ModuleShell>
}

export function TwinDashboard({notify,projectId}){
 const[live,setLive]=useState([]),[streams,setStreams]=useState([]),[tests,setTests]=useState([]),[calibrations,setCalibrations]=useState([]),[graph,setGraph]=useState({designs:[],simulations:[]}),[designId,setDesignId]=useState(''),[predicted,setPredicted]=useState(''),[actual,setActual]=useState(''),[busy,setBusy]=useState(false);
 const load=()=>Promise.all([api.telemetryLatest(projectId),api.telemetryStreams(),api.physicalTests(projectId),api.calibrations(projectId),api.graph(projectId)]).then(([l,allStreams,t,c,g])=>{const s=allStreams.filter(x=>x.projectId===projectId);setLive(l);setStreams(s);setTests(t);setCalibrations(c);setGraph(g);const current=g.designs?.find(x=>x.id===designId)||g.designs?.at(-1);setDesignId(current?.id||'');setPredicted(String(current?.metrics?.cd??''))}).catch(e=>notify(`디지털 트윈 동기화 실패 · ${e.message}`));useEffect(()=>{if(projectId){setLive([]);setTests([]);setCalibrations([]);setDesignId('');load()}},[projectId]);
 const value=signal=>live.find(x=>x.signal===signal),design=graph.designs?.find(x=>x.id===designId),latestCalibration=calibrations.find(x=>x.designId===designId)||calibrations[0],error=predicted&&actual?Math.abs((Number(actual)-Number(predicted))/Number(predicted)*100):null,level=error==null?'waiting':error<=3?'trusted':error<=7?'calibrate':error<=15?'additional_test':'investigate';
 const selectDesign=id=>{setDesignId(id);const d=graph.designs.find(x=>x.id===id),sim=graph.simulations.find(x=>x.designId===id&&x.type==='aero'&&x.status==='complete');setPredicted(String(sim?.result?.cd??d?.metrics?.cd??''));setActual('')};
 const record=async()=>{if(!design||!Number.isFinite(Number(predicted))||!Number.isFinite(Number(actual)))return notify('설계와 유효한 예측·실측값을 입력하세요');setBusy(true);try{const result=await api.recordPhysicalTest({projectId,designId:design.id,type:'wind_tunnel_correlation',metric:'drag_coefficient',domain:'aero',predicted:Number(predicted),actual:Number(actual),testId:`PHY-CORR-${Date.now()}`});notify(`실물 상관시험 저장 · 오차 ${result.calibration.errorPercent}% · ${result.calibration.decision}`);setActual('');load()}catch(e){notify(`실물시험 기록 실패 · ${e.message}`)}finally{setBusy(false)}};
 const signals=[['vehicle.speed','차량 속도','km/h','#66d8ff'],['battery.soc','배터리 SOC','%','#b8f500'],['power.consumption','소비 전력','kW','#d1a7ff'],['battery.temp','팩 최고 온도','°C','#f4b86c']];
 return <ModuleShell eyebrow="LIVE DIGITAL TWIN" title="가상 차량과 실차를 하나의 상태로." desc="실제 센서 스트림과 물리시험을 시뮬레이션 설계 버전에 연결하고, 오차 등급에 따라 모델 계수와 신뢰도를 보정합니다." action={<Button onClick={load}><RefreshCw size={14}/>{live.length?`LIVE · ${live.length} SIGNALS`:'센서 동기화'}</Button>}><div className="twin-status-strip"><label><span>상관 설계 버전</span><select value={designId} onChange={e=>selectDesign(e.target.value)}>{graph.designs?.map(x=><option value={x.id} key={x.id}>{x.id} · {x.name}</option>)}</select></label><div><small>센서 스트림</small><b>{streams.length}</b></div><div><small>물리 시험 증거</small><b>{tests.length}</b></div><div><small>모델 보정 이력</small><b>{calibrations.length}</b></div><em className={latestCalibration?.decision||'waiting'}>{latestCalibration?`${latestCalibration.decision} · confidence ${Math.round(latestCalibration.confidence*100)}%`:'NO CALIBRATION'}</em></div><div className="twin-live-grid"><div className="twin-car"><div className="canvas-grid"/><img src="/assets/urban-ev-concept.png" alt="실시간 센서 위치가 표시된 Urban E04 디지털 트윈"/>{value('battery.temp')&&<span className="sensor s1">T₁ {value('battery.temp').value} {value('battery.temp').unit}</span>}{value('body.vibration')&&<span className="sensor s2">V₄ {value('body.vibration').value} {value('body.vibration').unit}</span>}{value('tire.pressure')&&<span className="sensor s3">P₂ {value('tire.pressure').value} {value('tire.pressure').unit}</span>}{!live.length&&<div className="twin-no-data"><Activity size={28}/><b>실차 텔레메트리 대기</b><span>교정된 센서가 수집되면 차량 위치에 실제값을 표시합니다.</span></div>}</div><div className="telemetry"><div className="panel-title"><div><h3>최신 텔레메트리</h3>{live.length>0&&<span className="live-dot"/>}</div></div>{signals.map(([id,label,unit,color])=>{const sample=value(id);return <div className={`telemetry-row ${sample?'':'empty'}`} key={id}><span>{label}<b>{sample?.value??'—'}<small>{sample?.unit||unit}</small></b></span><div className="signal-line" style={{'--signal':color}}><i style={{width:sample?'100%':'0%'}}/></div><small>{sample?`${sample.sensorId||id} · ${new Date(sample.timestamp).toLocaleString()}`:'수집 데이터 없음'}</small></div>})}</div></div><div className="correlation-workspace"><section className="panel correlation-input"><div className="panel-title"><div><GitCompare size={14}/><h3>Sim-to-Real 상관시험</h3></div><span className={`correlation-grade ${level}`}>{error==null?'INPUT REQUIRED':`${error.toFixed(2)}% · ${level}`}</span></div><div className="correlation-values"><label><span>시뮬레이션 Cd</span><input inputMode="decimal" value={predicted} onChange={e=>setPredicted(e.target.value)}/></label><span>↔</span><label><span>풍동 실측 Cd</span><input inputMode="decimal" value={actual} onChange={e=>setActual(e.target.value)} placeholder="0.236"/></label></div><div className="error-bands"><span className={level==='trusted'?'active':''}><b>≤ 3%</b>신뢰</span><span className={level==='calibrate'?'active':''}><b>3–7%</b>보정</span><span className={level==='additional_test'?'active':''}><b>7–15%</b>추가시험</span><span className={level==='investigate'?'active':''}><b>&gt; 15%</b>오류조사</span></div><Button primary onClick={record}><Activity size={13}/>{busy?'보정 중…':'시험 증거 저장·모델 보정'}</Button></section><aside className="panel calibration-history"><div className="panel-title"><div><Timer size={14}/><h3>보정 계보</h3></div></div>{calibrations.length?calibrations.slice(0,6).map(x=><div className="calibration-row" key={x.id}><i className={x.decision}/><div><b>{x.domain} · {x.errorPercent}%</b><small>{x.designId||'unlinked'} · bias {x.previousParameters?.bias??0} → {x.newParameters?.bias??0}</small></div><em>{Math.round(x.confidence*100)}%</em></div>):<div className="empty-state small"><GitCompare size={24}/><span>저장된 실차 상관시험이 없습니다.</span></div>}</aside></div></ModuleShell>
}

export function BOMDashboard({notify,projectId}){
 const[q,setQ]=useState(''),[bom,setBom]=useState([]),[suppliers,setSuppliers]=useState([]),[designs,setDesigns]=useState([]),[evaluations,setEvaluations]=useState([]),[designId,setDesignId]=useState(''),[targetCost,setTargetCost]=useState(30000000),[busy,setBusy]=useState(false),[selectedPart,setSelectedPart]=useState('');
 const load=()=>Promise.all([api.bom(projectId),api.suppliers(),api.graph(projectId),api.manufacturingEvaluations()]).then(([b,s,g,allEvaluations])=>{const e=allEvaluations.filter(x=>x.projectId===projectId);setBom(b.items||[]);setSuppliers(s);setDesigns(g.designs||[]);setEvaluations(e);setDesignId(current=>g.designs?.some(x=>x.id===current)?current:g.designs?.at(-1)?.id||'')}).catch(e=>notify(`BOM 데이터 연결 실패 · ${e.message}`));useEffect(()=>{if(projectId){setBom([]);setEvaluations([]);setDesignId('');load()}},[projectId]);
 const evaluation=evaluations.find(x=>x.designId===designId)||evaluations[0],design=designs.find(x=>x.id===designId),supplierMap=Object.fromEntries(suppliers.map(x=>[x.id,x])),filtered=bom.filter(x=>`${x.partNo} ${x.description} ${x.system}`.toLowerCase().includes(q.toLowerCase())),direct=bom.reduce((n,x)=>n+x.qty*x.unitCost,0),riskParts=bom.filter(x=>x.status==='risk'||x.supplierIds?.some(id=>supplierMap[id]?.risk==='high')),local=bom.length?Math.round(bom.filter(x=>x.supplierIds?.some(id=>supplierMap[id]?.country==='KR')).length/bom.length*100):0;
 const evaluate=async()=>{if(!design)return notify('평가할 설계를 선택하세요');setBusy(true);try{const result=await api.manufacturingEvaluate({projectId,designId:design.id,parameters:design.parameters,targetCost:Number(targetCost)});setEvaluations(x=>[result,...x]);notify(`${design.id} 제조성 평가 · ${result.manufacturable?'통과':'개선 필요'}`)}catch(e){notify(`제조성 평가 실패 · ${e.message}`)}finally{setBusy(false)}};
 const exportCsv=()=>{const esc=x=>`"${String(x??'').replaceAll('"','""')}"`,lines=[['part_no','description','system','qty','unit_cost_krw','status','supplier_ids'],...bom.map(x=>[x.partNo,x.description,x.system,x.qty,x.unitCost,x.status,(x.supplierIds||[]).join('|')])].map(row=>row.map(esc).join(',')).join('\n'),url=URL.createObjectURL(new Blob([`\ufeff${lines}`],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`autoforge-bom-${designId||'project'}.csv`;a.click();URL.revokeObjectURL(url);notify(`${bom.length}개 실제 BOM 항목을 CSV로 내보냈습니다`)};
 const part=bom.find(x=>x.partNo===selectedPart),partResult=evaluation?.parts?.find(x=>x.partNo===selectedPart),alternatives=evaluation?.alternatives?.find(x=>x.partNo===selectedPart)?.alternatives||[];
 return <ModuleShell eyebrow="BOM & COST INTELLIGENCE" title="부품 하나까지 추적되는 제조원가." desc="실제 프로젝트 BOM·공급사·DFM 평가를 설계 버전과 연결하고 위험 부품의 대체 소싱 근거를 추적합니다." action={<Button primary onClick={exportCsv}><Download size={14}/>실제 BOM CSV</Button>}><div className="bom-eval-bar"><label><span>평가 설계</span><select value={designId} onChange={e=>setDesignId(e.target.value)}>{designs.map(x=><option key={x.id} value={x.id}>{x.id} · {x.name}</option>)}</select></label><label><span>목표 제조원가</span><input type="number" value={targetCost} onChange={e=>setTargetCost(e.target.value)}/></label><Button primary onClick={evaluate}><Factory size={13}/>{busy?'평가 중…':'DFM·공급망 평가'}</Button><em className={evaluation?.manufacturable?'pass':'risk'}>{evaluation?evaluation.manufacturable?'MANUFACTURABLE':'ACTION REQUIRED':'NOT EVALUATED'}</em></div><div className="bom-kpis"><div><small>평가 제조원가</small><b>{evaluation?`₩ ${(evaluation.cost.total/1e6).toFixed(2)}M`:`₩ ${(direct/1e6).toFixed(2)}M`}</b><em>{evaluation?`목표 대비 ${evaluation.cost.passed?'통과':'초과'}`:'직접 재료비'}</em></div><div><small>관리 BOM 항목</small><b>{bom.length}</b><em>{evaluation?`${evaluation.assembly.stations}개 조립 스테이션`:'평가 대기'}</em></div><div><small>공급 위험 부품</small><b>{riskParts.length}</b><em className={riskParts.length?'warn':''}>{evaluation?`위험 점수 ${evaluation.supplyRiskScore}`:'공급사 기준'}</em></div><div><small>국내 소싱 가능률</small><b>{local}%</b><em>{suppliers.length}개 공급사 연결</em></div></div><div className="bom-live-layout"><section className="bom-table"><div className="table-tools"><div><Search size={14}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="부품 번호·이름·시스템 검색"/></div><span>{filtered.length}/{bom.length} ITEMS</span></div><div className="tr th"><span>PART NUMBER</span><span>DESCRIPTION</span><span>SYSTEM</span><span>QTY</span><span>UNIT COST</span><span>STATUS</span></div>{filtered.map(x=><button onClick={()=>setSelectedPart(x.partNo)} className={`tr ${selectedPart===x.partNo?'selected':''}`} key={x.partNo}><span>{x.partNo}</span><span>{x.description}</span><span>{x.system}</span><span>{x.qty}</span><span>₩ {x.unitCost.toLocaleString()}</span><span className={`bom-state s-${x.status}`}>{x.status}</span></button>)}</section><aside className="panel sourcing-inspector"><div className="panel-title"><div><Truck size={14}/><h3>공급·대체 소싱</h3></div></div>{part?<><div className="sourcing-part"><span>{part.partNo}</span><b>{part.description}</b><small>{part.system} · extended ₩ {(part.qty*part.unitCost).toLocaleString()}</small></div><div className="supplier-list">{(part.supplierIds||[]).map(id=>supplierMap[id]).filter(Boolean).map(s=><div key={s.id} className={s.risk}><span><Truck size={12}/></span><div><b>{s.name}</b><small>{s.country} · {s.leadTimeDays}일 · {s.qualityPpm} PPM</small></div><em>{s.risk}</em></div>)}</div>{partResult?.risks?.length>0&&<div className="part-risks"><b>검출 위험</b>{partResult.risks.map(x=><span key={x}><AlertTriangle size={11}/>{x}</span>)}</div>}<div className="alternative-list"><b>검증된 대체 후보</b>{alternatives.length?alternatives.map(x=><span key={x.supplierId}><Check size={11}/><i>{x.name}</i><em>{x.leadTimeDays}일 · {x.risk}</em></span>):<small>{evaluation?'조건을 만족하는 신규 후보 없음':'제조성 평가 후 대체 공급사를 제안합니다.'}</small>}</div></>:<div className="empty-state small"><Package size={25}/><span>부품을 선택해 공급망 근거를 확인하세요.</span></div>}</aside></div></ModuleShell>
}

function ModuleShell({eyebrow,title,desc,action,children}){return <div className="module-page"><section className="module-banner"><div><span>{eyebrow}</span><h1>{title}</h1><p>{desc}</p></div>{action}</section>{children}</div>}
